// Original K Plus illustrations generated by scripts/art/gen.py (no third-party licences).
import art from "./art.json";

const A = art as { cat: Record<string, string>; prod: Record<string, string[]> };

/** Category illustration; admin-uploaded images always win where callers check them first. */
export const catArt = (slug: string): string | undefined => A.cat[slug];

/** Illustration for the i-th default product of a category, falling back to the category art. */
export const prodArt = (slug: string, i: number): string | undefined => A.prod[slug]?.[i] ?? A.cat[slug];
